import { z } from "zod";

export const createProjectSchema = z
  .object({
    project_name: z.string().min(1, "validation.required").max(255, "validation.project_name_max"),
    project_name_en: z.string().optional(),
    project_type: z.enum(["residential", "commercial", "mixed-use"], {
      message: "validation.required",
    }),
    total_units: z
      .string()
      .min(1, "projects.create.errors.totalUnitsRequired")
      .refine((val) => !isNaN(Number(val)) && Number(val) >= 0, {
        message: "projects.create.errors.totalUnitsPositive",
      }),
    available_units: z
      .string()
      .min(1, "projects.create.errors.availableUnitsRequired")
      .refine((val) => !isNaN(Number(val)) && Number(val) >= 0, {
        message: "projects.create.errors.availableUnitsPositive",
      }),
    launch_date: z.string().min(1, "projects.create.errors.launchDateRequired"),
    completion_date: z.string().optional(),
    delivery_date: z.string().optional(),
    unit_types: z.string().optional(),
    status: z.enum(["ongoing", "completed", "upcoming"], {
      message: "validation.required",
    }),
    currency: z.string().max(50, "validation.currency_max").optional(),
    min_price: z.string().optional(),
    max_price: z.string().optional(),
    price_sq_min: z.string().optional(),
    price_sq_max: z.string().optional(),
    price_range: z.string().optional(),
    price_range_SQ: z.string().optional(),
    description: z.string().optional(),
    project_size: z.string().optional(),
    developer_id: z.string().min(1, "validation.required"),

    latitude: z.number().min(-90).max(90),
    longitude: z.number().min(-180).max(180),
    landmark: z.string().max(255).optional(),
    city_id: z.string().min(1, "validation.required"),
    area_id: z.string().min(1, "projects.create.errors.areaRequired"),
    north_side: z.string().max(255).optional(),
    south_side: z.string().max(255).optional(),
    east_side: z.string().max(255).optional(),
    west_side: z.string().max(255).optional(),
    google_map_link: z.string().max(2048).url("validation.url_invalid"),
    location_description: z.string().optional(),

    is_active: z.enum(["0", "1", "2"]).optional(),
    milestone_id: z.string().optional(),
    phase: z.string().optional(),
    permit_no: z.string().max(20).optional(),
    barcode: z.any().optional(),
    slug: z.string().optional(),
    meta_title: z.string().optional(),
    meta_description: z.string().optional(),
  })
  .superRefine((data, ctx) => {
    if (data.launch_date && data.completion_date) {
      const launchDate = new Date(data.launch_date);
      const completionDate = new Date(data.completion_date);

      if (!isNaN(launchDate.getTime()) && !isNaN(completionDate.getTime()) && completionDate < launchDate) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "projects.create.errors.dateValidation",
          path: ["completion_date"],
        });
      }
    }

    if (data.total_units && data.available_units) {
      const total = Number(data.total_units);
      const available = Number(data.available_units);
      if (!isNaN(total) && !isNaN(available) && available > total) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: "projects.create.errors.availableExceedsTotal",
          path: ["available_units"],
        });
      }
    }
  });

export type CreateProjectInput = z.infer<typeof createProjectSchema>;